

'use strict';

// ===== DOM READY =====
document.addEventListener('DOMContentLoaded', () => {
  initScrollProgress();
  initNavigation();
  initHeroAnimations();
  initCounterAnimations();
  initCourseFilter();
  initFAQ();
  initScrollAnimations();
  initAnnouncementBar();
  initFormSubmission();
  initMarquee();
  initVideoFacades();
  initDeferredBackgrounds();
});

// ===== SCROLL PROGRESS BAR =====
function initScrollProgress() {
  const progressBar = document.createElement('div');
  progressBar.className = 'scroll-progress';
  document.body.prepend(progressBar);

  window.addEventListener('scroll', () => {
    const scrollTop = window.scrollY;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const progress = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
    progressBar.style.width = `${progress}%`;
  }, { passive: true });
}

// ===== NAVIGATION =====
function initNavigation() {
  const header = document.getElementById('main-header');

  // Sticky header on scroll
  if (header) {
    window.addEventListener('scroll', () => {
      if (window.scrollY > 50) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    }, { passive: true });
  }

  // Active nav link on scroll
  const sections = document.querySelectorAll('section[id]');
  const navLinksAll = document.querySelectorAll('.nav-link');

  if (sections.length > 0) {
    const sectionObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          navLinksAll.forEach(link => {
            link.classList.remove('active');
            if (link.getAttribute('href') === `#${entry.target.id}`) {
              link.classList.add('active');
            }
          });
        }
      });
    }, { rootMargin: '-30% 0px -60% 0px' });

    sections.forEach(section => sectionObserver.observe(section));
  }

  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;

      const target = document.querySelector(targetId);
      if (target) {
        e.preventDefault();
        const headerHeight = header ? header.offsetHeight : 0;
        const announcementBar = document.getElementById('announcement-bar');
        const announcementHeight = announcementBar ? announcementBar.offsetHeight : 0;
        const offset = headerHeight + announcementHeight + 16;

        window.scrollTo({
          top: target.offsetTop - offset,
          behavior: 'smooth'
        });
      }
    });
  });
}

// ===== HERO ANIMATIONS =====
function initHeroAnimations() {
  // Staggered entrance animation for hero elements
  const heroElements = [
    '.hero-badge',
    '.hero-title',
    '.hero-subtitle',
    '.hero-tagline',
    '.hero-ctas',
    '.hero-stats'
  ];

  heroElements.forEach((selector, index) => {
    const el = document.querySelector(selector);
    if (!el) return;

    el.style.opacity = '0';
    el.style.transform = 'translateY(24px)';
    el.style.transition = 'opacity 0.6s ease, transform 0.6s ease';

    setTimeout(() => {
      el.style.opacity = '1';
      el.style.transform = 'translateY(0)';
    }, 200 + (index * 120));
  });

  // Floating cards
  const floatingCards = document.querySelectorAll('.floating-card');
  floatingCards.forEach((card, index) => {
    card.style.opacity = '0';
    card.style.transform = 'translateX(30px)';
    card.style.transition = 'opacity 0.7s ease, transform 0.7s ease';

    setTimeout(() => {
      card.style.opacity = '1';
      card.style.transform = 'translateX(0)';
    }, 800 + (index * 200));
  });
}

// ===== COUNTER ANIMATIONS =====
function initCounterAnimations() {
  const statCards = document.querySelectorAll('.stat-card[data-count]');

  const counterObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting && !entry.target.dataset.animated) {
        entry.target.dataset.animated = 'true';
        const target = parseFloat(entry.target.dataset.count);
        const suffix = entry.target.dataset.suffix || '';
        const numberEl = entry.target.querySelector('.stat-number');

        if (!numberEl) return;

        animateCounter(numberEl, 0, target, 2000, suffix, target % 1 !== 0 ? 1 : 0);
      }
    });
  }, { threshold: 0.3 });

  statCards.forEach(card => counterObserver.observe(card));
}

function animateCounter(el, start, end, duration, suffix, decimals) {
  const startTime = performance.now();

  function update(currentTime) {
    const elapsed = currentTime - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = easeOutCubic(progress);
    const current = start + (end - start) * eased;

    el.textContent = current.toFixed(decimals) + suffix;

    if (progress < 1) {
      requestAnimationFrame(update);
    } else {
      el.textContent = end.toFixed(decimals) + suffix;
    }
  }

  requestAnimationFrame(update);
}

function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3);
}

// ===== COURSE FILTER =====
function initCourseFilter() {
  const tabs = document.querySelectorAll('.course-tab');
  const courseCards = document.querySelectorAll('.course-card');

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      // Update active tab
      tabs.forEach(t => {
        t.classList.remove('active');
        t.setAttribute('aria-selected', 'false');
      });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');

      const filter = tab.dataset.filter;

      // Filter course cards
      courseCards.forEach((card, index) => {
        const category = card.dataset.category;
        const matches = filter === 'all' || category === filter;

        if (matches) {
          card.style.display = 'flex';
          card.style.flexDirection = 'column';
          card.style.opacity = '0';
          card.style.transform = 'scale(0.95) translateY(10px)';
          card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';

          setTimeout(() => {
            card.style.opacity = '1';
            card.style.transform = 'scale(1) translateY(0)';
          }, index * 60);
        } else {
          card.style.opacity = '0';
          card.style.transform = 'scale(0.95)';
          setTimeout(() => {
            card.style.display = 'none';
          }, 200);
        }
      });
    });
  });
}

// ===== FAQ ACCORDION =====
function initFAQ() {
  const faqItems = document.querySelectorAll('.faq-item');

  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    const answer = item.querySelector('.faq-answer');

    if (!question || !answer) return;

    question.addEventListener('click', () => {
      const isExpanded = question.getAttribute('aria-expanded') === 'true';

      // Close all other FAQs
      faqItems.forEach(otherItem => {
        if (otherItem !== item) {
          const otherQuestion = otherItem.querySelector('.faq-question');
          const otherAnswer = otherItem.querySelector('.faq-answer');

          if (otherQuestion && otherAnswer) {
            otherQuestion.setAttribute('aria-expanded', 'false');
            otherAnswer.hidden = true;
          }
        }
      });

      // Toggle current FAQ
      if (isExpanded) {
        question.setAttribute('aria-expanded', 'false');
        answer.hidden = true;
      } else {
        question.setAttribute('aria-expanded', 'true');
        answer.hidden = false;
        // Smooth reveal
        answer.style.animation = 'fadeInUp 0.3s ease forwards';
      }
    });
  });
}

// ===== SCROLL ANIMATIONS =====
function initScrollAnimations() {
  // Add data-animate attribute to elements
  const animatableElements = [
    '.stat-card',
    '.academy-card',
    '.course-card',
    '.testimonial-card',
    '.mentor-card',
    '.process-step',
    '.project-card',
    '.placement-stat',
    '.why-feature',
    '.highlight-item',
    '.journey-step',
    '.faq-item',
  ];

  animatableElements.forEach(selector => {
    document.querySelectorAll(selector).forEach((el, index) => {
      el.dataset.animate = 'true';
      el.style.transitionDelay = `${(index % 4) * 0.08}s`;
    });
  });

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, {
    threshold: 0.1,
    rootMargin: '0px 0px -40px 0px'
  });

  document.querySelectorAll('[data-animate]').forEach(el => observer.observe(el));

  // Section headers slide in
  document.querySelectorAll('.section-header, .why-content, .cert-content').forEach(el => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(30px)';
    el.style.transition = 'opacity 0.7s ease, transform 0.7s ease';

    const headerObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
          headerObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.2 });

    headerObserver.observe(el);
  });
}

// ===== ANNOUNCEMENT BAR =====
function initAnnouncementBar() {
  const closeBtn = document.getElementById('close-announcement');
  const bar = document.getElementById('announcement-bar');

  if (!closeBtn || !bar) return;

  closeBtn.addEventListener('click', () => {
    bar.style.maxHeight = bar.offsetHeight + 'px';
    bar.style.transition = 'max-height 0.3s ease, opacity 0.3s ease, padding 0.3s ease';

    requestAnimationFrame(() => {
      bar.style.maxHeight = '0';
      bar.style.opacity = '0';
      bar.style.padding = '0';
      bar.style.overflow = 'hidden';
    });

    setTimeout(() => {
      bar.style.display = 'none';
    }, 300);
  });
}

// ===== FORM SUBMISSION =====
function initFormSubmission() {
  const form = document.getElementById('counselling-form');
  if (!form) return;

  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const submitBtn = form.querySelector('#counselling-submit');
    const nameEl = document.getElementById('full-name');
    const phoneEl = document.getElementById('phone');
    const emailEl = document.getElementById('email');
    const courseEl = document.getElementById('course-interest');

    const name = nameEl ? nameEl.value.trim() : '';
    const phone = phoneEl ? phoneEl.value.trim() : '';

    if (!name) {
      showFormError('full-name', 'Please enter your full name');
      return;
    }

    if (!phone || phone.replace(/\D/g, '').length < 10) {
      showFormError('phone', 'Please enter a valid 10-digit phone number');
      return;
    }

    const course = courseEl ? (courseEl.options[courseEl.selectedIndex]?.text || courseEl.value) : '';

    await submitNovaForm({
      form,
      submitBtn,
      loadingText: 'Booking...',
      data: {
        name,
        mobile: phone,
        email: emailEl ? emailEl.value.trim() : '',
        course
      }
    });
  });
}

function showFormError(fieldId, message) {
  const field = document.getElementById(fieldId);
  if (!field) return;

  field.style.borderColor = 'rgba(239, 68, 68, 0.7)';
  field.focus();

  // Remove error after typing
  field.addEventListener('input', () => {
    field.style.borderColor = '';
  }, { once: true });
}

// ===== MARQUEE PAUSE ON HOVER =====
function initMarquee() {
  const track = document.querySelector('.partners-track');
  const wrapper = document.querySelector('.partners-marquee-wrapper');

  if (!track || !wrapper) return;

  wrapper.addEventListener('mouseenter', () => {
    track.style.animationPlayState = 'paused';
  });

  wrapper.addEventListener('mouseleave', () => {
    track.style.animationPlayState = 'running';
  });
}

